            "easy2_desc": "그래서 연구진은 네트워크 전체가 n-gram 표를 같이 쓰되 각 층마다 다르게 읽어 들이는 코러스(Chorus)를 제안했는데요, 층마다 현재 숨은 상태에서 계산된 값으로 성분을 조정한 뒤 각자의 투영 층을 거쳐 임베딩을 매핑하는 방식이에요. 이렇게 했더니 기존 87%나 더 작은 표 크기로도 기존 n-gram 방식과 똑같은 품질을 냈다고 하는데요, 1.2B 규모의 표 파라미터만으로도 9.6B를 쓰는 팩터엔그램(FactorEngram)이나 딥식(DeepSeek)의 엔그램(Engram)보다 텍스트 예측을 더 잘했다고 해요. 쉽게 말하면, 메모리는 훨씬 아끼면서도 성능은 더 좋아졌다는 셈이에요.",
