            "easy1_desc": "종래의 오랜 시간 일하는 거대 언어 모델(LLM) 에이전트는 모든 이전 행동과 관찰을 그대로 쌓아 두는 방식으로 문맥을 넘겨줬는데요. 이렇게 실행이 진행될수록 기록이 계속 불어나는 바람에 추론 비용이 늘어나고 정확도가 떨어질 위험이 생긴다는 겁니다. 기존 방법들은 앞선 관찰을 지우고 압축된 결론만 남기는 식으로 이 크기를 조절해 왔는데요. 문제는 그러다 보면 나중에 꼭 필요해지는 증거까지 함께 버려지게 된다는 말이에요. 결국 정보를 다 담자니 비용이 커지고, 줄이자니 핵심 단서를 잃는 문제가 있었다는 셈입니다.",
