            "easy1_desc": "연구진은 AI(인공지능) 시스템의 성능을 예측하려고 할 때 새로운 대형 모델을 또 쓸 필요는 없다고 보았는데요, 공개된 평가 횟수를 바탕으로 약한 베타 사전 확률(Beta prior)을 잡고 이를 최대 31개의 공개된 결과로 정확하게 업데이트하는 방식을 썼습니다. 이 예측기는 아이템의 의미나 사전 학습된 가중치, 추론 API를 전혀 쓰지 않는데요, 그 결과 AIMS 대회에서 팀이 보고한 브리어 ALC(Brier Area under the Learning Curve) 0.188477을 기록해 상수 0.5 기준선보다 24.6% 줄어든 성능을 보였다는 겁니다. 전체 제출본의 크기는 7,754바이트이고 서버 마이크로벤치마크에서는 31개의 일치하는 레이블과 함께 예측당 12.71마이크로초를 기록했다고 해요.",
            "easy2_title": "가벼운 베이지안 모델로 적은 피드백에서도 빠르고 정확하게 불확실성을 쟀습니다",
