            "easy1_desc": "비디오 생성에서 중요한 역할을 하는 비디오 평가기가 움직임 결함을 자주 놓쳐서 영상 품질을 떨어뜨린다는 점이 문제였는데요. 기존의 자기 개선 방식인 RSI는 명확한 검증기가 있는 수학이나 코딩에서는 잘 통했지만, 정답 검증기가 없고 물리 법칙이나 부드러움 같은 여러 차원을 동시에 평가해야 하는 비디오 평가에서는 그대로 쓰기 어려웠거든요. 결국 한쪽이 좋아지면 다른 쪽이 나빠지는 문제가 생겨서, 이런 제약 속에서도 스스로 발전할 수 있는 구조가 필요했다는 말이에요.",
