            "easy1_desc": "이미 학습이 끝나서 가중치를 바꿀 수 없는 멀티모달 모델이 있는데, 갑자기 입력 데이터 중 일부가 사라지는 상황이 생길 수 있거든요. 이때 남은 정보만으로 모델의 오류를 얼마나 고칠 수 있는지, 혹은 아예 고칠 수 없는 오류인지를 판단하는 게 중요합니다. 연구진은 이 고칠 수 있는 오류의 범위를 베이즈 갭(Bayes gap)이라는 개념으로 설명했는데요. 쉽게 말하면, 모델이 내놓은 예측값과 실제 관측된 정보 사이의 차이를 분석해서 수정 가능 여부를 따져본다는 겁니다.",
