            "easy1_desc": "연구진은 로봇 부품과 모터, 맞춤형 3D 프린팅 부품을 가지고 에이전트가 로봇의 하드웨어와 프로그램을 함께 설계하는 벤치마크인 로보빌더(RoboBuilder)를 도입했는데요. 시뮬레이션을 통과한 모든 설계를 실제 물리 코스에서 직접 만들고 테스트해 봤더니, 시뮬레이션만으로는 부족해서 처음 15개의 설계 모두 실제 코스를 건너지 못했다고 해요. 그래서 에이전트가 요청한 측정값과 실제 주행 영상으로 시뮬레이터를 학습하도록 만들었다는 겁니다. 쉽게 말하면, 가상 속에서만 잘 되는 게 아니라 현실의 벽에 부딪혀 시행착오를 겪었다는 셈이에요.",
            "easy2_title": "실제 주행 영상을 보여주었더니 설계 오류를 고치고 실패율을 줄였다",
