            "easy1_desc": "연구진은 여섯 가지 시각-언어 모델(VLM) 에이전트에게 2025년 3월부터 2026년 8월 사이에 공개된 응급 컴퓨터단층촬영(CT) 및 자기공명영상(MRI) 검사 100건을 읽혀 봤는데요, 탐색 방식에 따라 진단 정확도가 어떻게 달라지는지 살펴본 겁니다. 그랬더니 자유롭게 돌아보며 읽을 때 정확도가 32.6%로 가장 낮았고, 주요 단면 한 장에서 시작할 때는 37.9%, 모든 단면이나 주요 단면을 한 번에 받을 때는 각각 42.2%와 42.5%로 나타났다는 거예요. 쉽게 말하면, AI가 스스로 영상을 찾아보게 하는 것보다 필요한 영상을 한꺼번에 쥐여줄 때 정답률이 더 올라간 셈이라는 말이에요.",
            "easy2_title": "인간 의사와 비교해 보니 무엇이 달라졌나",
            "easy2_desc": "그래서 인간 방사선과 의사 아홉 명이 직접 읽은 30건과 비교해 봤더니, 의사들은 77.0%를 맞춘 반면 자유롭게 탐색하는 AI는 30.0%를 맞추는 데 그쳤다는 겁니다. 모델들은 전체 단면의 10.8%만 보고 첫 가설을 세운 뒤 이를 63.1%의 실행에서 끝까지 고수했는데요, 첫 가설이 틀렸을 때 나중에 맞출 확률은 12.4%에 불과했다는 단점이 있는 반면, 맞았을 때는 90.4%로 올라갔다는 장점이 있다는 거예요. 게다가 최종 답안에 대한 스스로의 확신은 90%에 달했지만 실제 정답률은 38.9%에 그쳤다는 점에서, AI가 섣부른 판단을 고치지 못하는 한계가 함께 나타났다는 겁니다.",
