            "easy2_desc": "그래서 연구진은 채점자가 따로 필요 없는 가드(GUARD, Grader-free Unsupervised Environment Design with Adaptive Rule Distillation)라는 틀을 만들어 도입했는데요. 문제를 실행하기 전에 스스로 확인하게 쪼개고, 새로 망가진 행동을 먼저 챙기면서 이득이 손해보다 클 때만 고친 내용을 적용하는 방식이에요. 이렇게 하니까 옛날 걸 까먹거나 기억이 오염되는 일 없이 성능이 꾸준히 좋아지고 배포할 때 쓰는 토큰(Token) 사용량도 확 줄어든다는 장점이 생겼다는 겁니다. 대신 규칙을 너무 자주 건드리지 않게 꽉 잡는 과정이 꼭 같이 따라온다는 점도 있다는 거예요.",
