            "easy1_desc": "연구진은 9개의 주요 실증 평가와 516개의 독창적인 다중 에이전트 구성을 모아서 분석해 봤는데요. 기존 연구들처럼 단순한 단일 패스 기준과 비교했을 때는 정확도 차이가 전체적으로 음수이거나 거의 0에 가까웠다는 겁니다. 샘플 수나 자원 예산을 똑같이 맞춘 기준과 비교했을 때도 다중 에이전트 시스템은 정확도가 평균 -0.042를 기록했는데요. 비교 가능한 대조군의 74%에서 다중 에이전트 정확도가 기준선과 같거나 그보다 떨어지는 결과로 나타났다는 말이에요.",
